import json,sys
for f in ["2302b45d-bcfe-4be3-8c6a-84819e2f6191","77407836-b974-40ea-96f0-bff2e237e95e"]:
    p=f".claude-home/projects/-home-runner-workspace/{f}.jsonl"
    rows=[]
    with open(p) as fh:
        for line in fh:
            try: rows.append(json.loads(line))
            except: pass
    print("="*100)
    print(f, "rows:", len(rows))
    # first real user message
    for r in rows[:40]:
        if r.get("type")=="user":
            m=r.get("message",{})
            c=m.get("content")
            if isinstance(c,str): t=c
            else: t=" ".join(x.get("text","") for x in c if isinstance(x,dict) and x.get("type")=="text")
            if t.strip() and "<command-name>" not in t and "system-reminder" not in t[:60]:
                print("--- FIRST USER MSG ---")
                print(t[:2500])
                break
    print("--- LAST 6 USER MSGS ---")
    us=[]
    for r in rows:
        if r.get("type")=="user":
            m=r.get("message",{})
            c=m.get("content")
            if isinstance(c,str): t=c
            else:
                t=" ".join(x.get("text","") for x in c if isinstance(x,dict) and x.get("type")=="text")
            if t.strip() and "tool_result" not in t:
                us.append(t)
    for t in us[-6:]:
        print("  >>>", t[:1200].replace("\n"," | "))
    print("--- LAST 3 ASSISTANT TEXTS ---")
    as_=[]
    for r in rows:
        if r.get("type")=="assistant":
            c=r.get("message",{}).get("content",[])
            t=" ".join(x.get("text","") for x in c if isinstance(x,dict) and x.get("type")=="text")
            if t.strip(): as_.append(t)
    for t in as_[-3:]:
        print("  <<<", t[:2500])
