import json
for f in ["77407836-b974-40ea-96f0-bff2e237e95e","2302b45d-bcfe-4be3-8c6a-84819e2f6191"]:
    p=f".claude-home/projects/-home-runner-workspace/{f}.jsonl"
    rows=[json.loads(l) for l in open(p) if l.strip()]
    print("="*80); print(f)
    ids={}
    for r in rows:
        if r.get("type")=="assistant":
            for c in r.get("message",{}).get("content",[]):
                if isinstance(c,dict) and c.get("type")=="tool_use" and c.get("name")=="Artifact":
                    inp=c.get("input",{})
                    ids[c["id"]]={k:v for k,v in inp.items() if k in ("action","file_path","url","title","label")}
    for r in rows:
        if r.get("type")=="user":
            cc=r.get("message",{}).get("content",[])
            if isinstance(cc,list):
                for c in cc:
                    if isinstance(c,dict) and c.get("type")=="tool_result" and c.get("tool_use_id") in ids:
                        t=c.get("content")
                        if isinstance(t,list): t=" ".join(x.get("text","") for x in t if isinstance(x,dict))
                        print(ids[c["tool_use_id"]], "->", str(t)[:400].replace("\n"," "))
PY

