<title>The Blue Box and the Dock</title>
<style>
  :root {
    --ground:      #F1F3F8;
    --surface:     #FFFFFF;
    --surface-2:   #E9EDF6;
    --navy:        #040D6D;
    --dock-navy:   #02093D;

    --ink:         #0B1338;
    --ink-2:       #4A5378;
    --ink-3:       #838CAB;

    --accent:      #1F6FE0;
    --accent-soft: #58ABFF;
    --accent-wash: #E3EDFC;

    --spill:       #BE3346;
    --spill-wash:  #FBE7EA;
    --good:        #0B8F62;
    --good-wash:   #E0F4EC;

    --line:        #D9DEEC;
    --line-soft:   #E7EBF4;
    --shadow:      0 1px 2px rgba(11,19,56,.05), 0 8px 24px -12px rgba(11,19,56,.18);

    --display: "Outfit", "Avenir Next", "Segoe UI Variable Display", system-ui, -apple-system, sans-serif;
    --body: system-ui, -apple-system, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    --data: ui-monospace, "SF Mono", SFMono-Regular, "JetBrains Mono", Menlo, Consolas, monospace;

    --col: 68ch;
    --gutter: 88px;
  }

  @media (prefers-color-scheme: dark) {
    :root:not([data-theme="light"]) {
      --ground:      #060A22;
      --surface:     #0C1231;
      --surface-2:   #121A40;
      --navy:        #061276;
      --dock-navy:   #02093D;
      --ink:         #E9ECF7;
      --ink-2:       #A3ABC9;
      --ink-3:       #6D779C;
      --accent:      #74B6FF;
      --accent-soft: #58ABFF;
      --accent-wash: #13224C;
      --spill:       #FF8592;
      --spill-wash:  #35141C;
      --good:        #45D9A4;
      --good-wash:   #0C2C22;
      --line:        #1F2A56;
      --line-soft:   #162044;
      --shadow:      0 1px 2px rgba(0,0,0,.4), 0 8px 28px -14px rgba(0,0,0,.7);
    }
  }
  :root[data-theme="dark"] {
    --ground:      #060A22;
    --surface:     #0C1231;
    --surface-2:   #121A40;
    --navy:        #061276;
    --dock-navy:   #02093D;
    --ink:         #E9ECF7;
    --ink-2:       #A3ABC9;
    --ink-3:       #6D779C;
    --accent:      #74B6FF;
    --accent-soft: #58ABFF;
    --accent-wash: #13224C;
    --spill:       #FF8592;
    --spill-wash:  #35141C;
    --good:        #45D9A4;
    --good-wash:   #0C2C22;
    --line:        #1F2A56;
    --line-soft:   #162044;
    --shadow:      0 1px 2px rgba(0,0,0,.4), 0 8px 28px -14px rgba(0,0,0,.7);
  }

  * { box-sizing: border-box; }

  body {
    margin: 0;
    background: var(--ground);
    color: var(--ink);
    font-family: var(--body);
    font-size: 16px;
    line-height: 1.62;
    -webkit-font-smoothing: antialiased;
  }
  .page { max-width: calc(var(--gutter) + var(--col) + 96px); margin: 0 auto; padding: 0 24px 120px; }

  header.mast { padding: 76px 0 34px; }
  .eyebrow {
    font-family: var(--data); font-size: 11.5px; letter-spacing: .16em;
    text-transform: uppercase; color: var(--ink-3); margin: 0 0 20px;
  }
  h1 {
    font-family: var(--display); font-weight: 800; letter-spacing: -0.045em;
    font-size: clamp(40px, 6.6vw, 70px); line-height: .98; margin: 0 0 22px; text-wrap: balance;
  }
  h1 em { font-style: normal; color: var(--accent); }
  .standfirst {
    font-size: clamp(17px, 2.1vw, 20px); line-height: 1.5; color: var(--ink-2);
    max-width: 60ch; margin: 0 0 30px;
  }
  .meta { display: flex; flex-wrap: wrap; gap: 8px 10px; font-family: var(--data); font-size: 12px; color: var(--ink-2); }
  .meta span { border: 1px solid var(--line); border-radius: 3px; padding: 4px 9px; background: var(--surface); }
  .meta span b { font-weight: 600; color: var(--ink); }

  .ticks {
    height: 9px;
    background:
      repeating-linear-gradient(to right, var(--line) 0 1px, transparent 1px 12px) bottom / 100% 5px no-repeat,
      linear-gradient(to right, var(--line), var(--line)) bottom / 100% 1px no-repeat;
  }

  section { padding-top: 58px; }
  .sec-head { display: grid; grid-template-columns: var(--gutter) minmax(0,1fr); gap: 0 8px; align-items: baseline; margin-bottom: 22px; }
  .sec-num { font-family: var(--data); font-size: 12px; letter-spacing: .1em; color: var(--accent); padding-top: 6px; }
  h2 { font-family: var(--display); font-weight: 700; letter-spacing: -0.032em; font-size: clamp(25px, 3.4vw, 33px); line-height: 1.12; margin: 0; text-wrap: balance; }
  h3 { font-family: var(--display); font-weight: 700; letter-spacing: -0.022em; font-size: 19px; line-height: 1.25; margin: 0 0 8px; }

  .body { display: grid; grid-template-columns: var(--gutter) minmax(0,1fr); gap: 0 8px; }
  .body > .rail { font-family: var(--data); font-size: 11px; letter-spacing: .1em; text-transform: uppercase; color: var(--ink-3); padding-top: 7px; }
  .body > .flow { min-width: 0; }
  .flow > * + * { margin-top: 16px; }
  .flow p { margin: 0; max-width: var(--col); }
  .flow ul { margin: 0; padding-left: 20px; max-width: var(--col); }
  .flow li + li { margin-top: 7px; }

  @media (max-width: 700px) {
    .sec-head, .body { grid-template-columns: 1fr; }
    .body > .rail { padding: 0 0 8px; }
    :root { --gutter: 0px; }
  }

  code, .num { font-family: var(--data); font-size: .88em; font-variant-numeric: tabular-nums; }
  code { background: var(--surface-2); border-radius: 3px; padding: 1px 5px; color: var(--ink); overflow-wrap: anywhere; }
  a { color: var(--accent); }
  a:focus-visible, button:focus-visible { outline: 2px solid var(--accent); outline-offset: 3px; border-radius: 4px; }

  .tw { overflow-x: auto; border: 1px solid var(--line); border-radius: 5px; background: var(--surface); box-shadow: var(--shadow); }
  table { border-collapse: collapse; width: 100%; min-width: 480px; font-size: 14.5px; }
  th, td { text-align: left; padding: 10px 14px; border-bottom: 1px solid var(--line-soft); vertical-align: top; }
  thead th {
    font-family: var(--data); font-size: 11px; letter-spacing: .09em; text-transform: uppercase;
    color: var(--ink-3); font-weight: 600; background: var(--surface-2);
    border-bottom: 1px solid var(--line); white-space: nowrap;
  }
  tbody tr:last-child td { border-bottom: 0; }
  td.n, th.n { font-family: var(--data); font-variant-numeric: tabular-nums; white-space: nowrap; }
  .spill { color: var(--spill); font-weight: 600; }
  .ok { color: var(--good); font-weight: 600; }

  .card { background: var(--surface); border: 1px solid var(--line); border-radius: 5px; padding: 22px 24px; box-shadow: var(--shadow); }
  .card > * + * { margin-top: 13px; }
  .card p { margin: 0; max-width: var(--col); }
  .where { font-family: var(--data); font-size: 12px; color: var(--ink-3); }

  pre { margin: 0; background: var(--surface-2); border: 1px solid var(--line-soft); border-radius: 4px; padding: 13px 15px; overflow-x: auto; font-family: var(--data); font-size: 12.5px; line-height: 1.55; color: var(--ink); }
  pre code { background: none; padding: 0; font-size: inherit; }

  figure { margin: 0; }
  figcaption { font-family: var(--data); font-size: 11.5px; color: var(--ink-3); margin-top: 10px; line-height: 1.5; }

  /* ─────────── panel-overflow diagram ─────────── */
  .phones { display: flex; flex-wrap: wrap; gap: 22px; }
  .phone-fig { flex: 0 0 auto; }
  .phone {
    position: relative;
    width: 104px;
    border: 2px solid var(--ink-3);
    border-radius: 12px;
    background: var(--surface-2);
    overflow: visible;
  }
  .phone-clip { position: relative; overflow: hidden; border-radius: 10px; }
  .p-hero { background: var(--surface); }
  .p-navy { background: var(--navy); }
  .p-spill {
    background: repeating-linear-gradient(-45deg, var(--spill) 0 3px, transparent 3px 7px);
    border-top: 1px dashed var(--spill);
    opacity: .85;
  }
  .p-dock {
    position: absolute; left: 12px; right: 12px; bottom: 6px; height: 11px;
    background: var(--dock-navy); border-radius: 6px;
    outline: 1.5px dashed var(--accent-soft); outline-offset: 2px;
  }
  .phone-label { font-family: var(--data); font-size: 11px; color: var(--ink-2); margin-top: 9px; text-align: center; }
  .phone-note { font-family: var(--data); font-size: 10.5px; color: var(--spill); text-align: center; }

  .legend { display: flex; flex-wrap: wrap; gap: 16px; font-family: var(--data); font-size: 11.5px; color: var(--ink-3); }
  .legend i { font-style: normal; }
  .sw { display: inline-block; width: 11px; height: 11px; border-radius: 2px; vertical-align: -1px; margin-right: 5px; }

  /* ─────────── tap zone diagram ─────────── */
  .tapzone {
    position: relative; height: 88px; border-radius: 6px;
    background: var(--surface-2); border: 1px solid var(--line);
    display: flex; align-items: center; justify-content: center;
  }
  .tz-region {
    position: absolute; left: 8%; right: 8%; top: 18px; bottom: 18px;
    background: var(--spill-wash); border: 1.5px dashed var(--spill); border-radius: 5px;
  }
  .tz-handle { position: relative; width: 56px; height: 4px; border-radius: 999px; background: var(--dock-navy); }
  .tz-tag {
    position: absolute; font-family: var(--data); font-size: 10.5px; letter-spacing: .04em;
  }
  .tz-tag.a { color: var(--spill); left: 8%; top: 2px; }
  .tz-tag.b { color: var(--ink-2); left: 50%; transform: translateX(-50%); bottom: 2px; }

  /* ─────────── the live goo demo ─────────── */
  .goo-demo {
    background: var(--surface); border: 1px solid var(--line); border-radius: 6px;
    padding: 26px 24px 22px; box-shadow: var(--shadow);
  }
  .goo-stage {
    height: 92px; border-radius: 6px;
    background: linear-gradient(180deg, var(--accent-wash), var(--surface-2));
    display: flex; align-items: center; justify-content: center;
    overflow: hidden;
  }
  .goo-dock { position: relative; width: 280px; height: 58px; }
  .goo-layer-a { position: absolute; inset: 0; }
  .goo-layer-a.morphing { filter: url(#dockGoo); }
  .blob {
    position: absolute; top: 50%; left: 50%; background: var(--dock-navy); border-radius: 999px;
    width: var(--w); height: var(--h);
    transform: translate(-50%,-50%) translateX(var(--x));
    transition: width .46s cubic-bezier(.65,0,.35,1),
                height .46s cubic-bezier(.65,0,.35,1),
                transform .46s cubic-bezier(.65,0,.35,1);
  }
  .goo-dock[data-state="open"]   .blob { --x: calc((var(--i) - 2) * 56px); --w: 62px; --h: 48px; }
  .goo-dock[data-state="closed"] .blob { --x: calc((var(--i) - 2) * 5px);  --w: 26px; --h: 4px;  }
  /* the bar body: at rest it makes the silhouette a clean pill, so the resting dock
     never shows the seams between slots. It collapses with everything else. */
  .blob.bar { border-radius: 24px; }
  .goo-dock[data-state="open"]   .blob.bar { --x: 0px; --w: 280px; --h: 48px; }
  .goo-dock[data-state="closed"] .blob.bar { --x: 0px; --w: 56px;  --h: 4px;  }

  .goo-layer-b { position: absolute; inset: 0; display: flex; align-items: center; justify-content: space-around; padding: 0 16px; }
  .goo-icon {
    color: var(--accent-soft); display: flex; opacity: 1; transform: scale(1);
    transition: opacity .17s ease .2s, transform .3s cubic-bezier(.34,1.56,.64,1) .16s;
  }
  .goo-dock[data-state="closed"] .goo-icon { opacity: 0; transform: scale(.62); transition-delay: 0s; }
  .goo-icon.active { color: #FFFFFF; }

  .goo-controls { display: flex; flex-wrap: wrap; gap: 10px; align-items: center; margin-top: 16px; }
  .goo-btn {
    font-family: var(--data); font-size: 12px; letter-spacing: .04em;
    background: var(--accent); color: #FFFFFF; border: none; border-radius: 4px;
    padding: 8px 14px; cursor: pointer;
  }
  .goo-btn.ghost { background: transparent; color: var(--accent); border: 1px solid var(--line); }
  .goo-state { font-family: var(--data); font-size: 11.5px; color: var(--ink-3); }

  @media (prefers-reduced-motion: reduce) {
    .blob, .goo-icon { transition-duration: .01ms !important; }
    .goo-layer-a.morphing { filter: none; }
  }

  /* ─────────── phases ─────────── */
  .phases { display: grid; gap: 10px; }
  .phase {
    display: grid; grid-template-columns: 44px minmax(0,1fr); gap: 0 16px;
    background: var(--surface); border: 1px solid var(--line);
    border-left: 3px solid var(--accent-soft); border-radius: 4px; padding: 16px 18px;
  }
  .phase-n { font-family: var(--display); font-weight: 800; font-size: 24px; letter-spacing: -0.04em; color: var(--ink-3); line-height: 1; }
  .phase p { margin: 0; color: var(--ink-2); font-size: 15px; max-width: 62ch; }
  .phase .gate { margin-top: 9px; font-family: var(--data); font-size: 11.5px; color: var(--ink-3); }
  .phase .gate b { color: var(--ink-2); font-weight: 600; }

  .decision { background: var(--surface); border: 1px solid var(--line); border-radius: 5px; padding: 18px 20px; }
  .decision + .decision { margin-top: 10px; }
  .decision p { margin: 0; color: var(--ink-2); font-size: 15px; }
  .decision p + p { margin-top: 8px; }
  .rec {
    font-family: var(--data); font-size: 11px; letter-spacing: .06em; text-transform: uppercase;
    color: var(--good); background: var(--good-wash); padding: 2px 7px; border-radius: 3px;
    margin-left: 6px; white-space: nowrap;
  }

