<title>The 44-Pixel Rule</title>
<style>
  /* ─────────── tokens: light is the base set ─────────── */
  :root {
    --ground:      #F1F3F8;
    --surface:     #FFFFFF;
    --surface-2:   #E9EDF6;
    --deep:        #040D6D;   /* the product's navy — used as a deep panel */
    --deep-ink:    #BFD8FF;

    --ink:         #0B1338;
    --ink-2:       #4A5378;
    --ink-3:       #838CAB;

    --accent:      #1F6FE0;
    --accent-soft: #58ABFF;   /* the product's blue */
    --accent-wash: #E3EDFC;

    --bad:         #BE3346;
    --bad-wash:    #FBE7EA;
    --good:        #0B8F62;
    --good-wash:   #E0F4EC;

    --line:        #D9DEEC;
    --line-soft:   #E7EBF4;

    --shadow:      0 1px 2px rgba(11,19,56,.05), 0 8px 24px -12px rgba(11,19,56,.18);

    --display: "Outfit", "Avenir Next", "Segoe UI Variable Display", system-ui, -apple-system, sans-serif;
    --body: system-ui, -apple-system, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    --data: ui-monospace, "SF Mono", SFMono-Regular, "JetBrains Mono", Menlo, Consolas, monospace;

    --col: 68ch;
    --gutter: 88px;
  }

  @media (prefers-color-scheme: dark) {
    :root:not([data-theme="light"]) {
      --ground:      #060A22;
      --surface:     #0C1231;
      --surface-2:   #121A40;
      --deep:        #020730;
      --deep-ink:    #8FBEFF;

      --ink:         #E9ECF7;
      --ink-2:       #A3ABC9;
      --ink-3:       #6D779C;

      --accent:      #74B6FF;
      --accent-soft: #58ABFF;
      --accent-wash: #13224C;

      --bad:         #FF8592;
      --bad-wash:    #35141C;
      --good:        #45D9A4;
      --good-wash:   #0C2C22;

      --line:        #1F2A56;
      --line-soft:   #162044;

      --shadow:      0 1px 2px rgba(0,0,0,.4), 0 8px 28px -14px rgba(0,0,0,.7);
    }
  }

  :root[data-theme="dark"] {
    --ground:      #060A22;
    --surface:     #0C1231;
    --surface-2:   #121A40;
    --deep:        #020730;
    --deep-ink:    #8FBEFF;

    --ink:         #E9ECF7;
    --ink-2:       #A3ABC9;
    --ink-3:       #6D779C;

    --accent:      #74B6FF;
    --accent-soft: #58ABFF;
    --accent-wash: #13224C;

    --bad:         #FF8592;
    --bad-wash:    #35141C;
    --good:        #45D9A4;
    --good-wash:   #0C2C22;

    --line:        #1F2A56;
    --line-soft:   #162044;

    --shadow:      0 1px 2px rgba(0,0,0,.4), 0 8px 28px -14px rgba(0,0,0,.7);
  }

  * { box-sizing: border-box; }

  body {
    margin: 0;
    background: var(--ground);
    color: var(--ink);
    font-family: var(--body);
    font-size: 16px;
    line-height: 1.62;
    -webkit-font-smoothing: antialiased;
  }

  .page {
    max-width: calc(var(--gutter) + var(--col) + 96px);
    margin: 0 auto;
    padding: 0 24px 120px;
  }

  /* ─────────── the measurement rule: a caliper tick strip ─────────── */
  .ticks {
    height: 9px;
    background:
      repeating-linear-gradient(to right, var(--line) 0 1px, transparent 1px 12px) bottom / 100% 5px no-repeat,
      linear-gradient(to right, var(--line), var(--line)) bottom / 100% 1px no-repeat;
  }

  /* ─────────── masthead ─────────── */
  header.mast {
    padding: 76px 0 34px;
  }
  .eyebrow {
    font-family: var(--data);
    font-size: 11.5px;
    letter-spacing: .16em;
    text-transform: uppercase;
    color: var(--ink-3);
    margin: 0 0 20px;
  }
  h1 {
    font-family: var(--display);
    font-weight: 800;
    letter-spacing: -0.045em;
    font-size: clamp(42px, 7vw, 74px);
    line-height: .96;
    margin: 0 0 22px;
    text-wrap: balance;
  }
  h1 em {
    font-style: normal;
    color: var(--accent);
  }
  .standfirst {
    font-size: clamp(17px, 2.1vw, 20px);
    line-height: 1.5;
    color: var(--ink-2);
    max-width: 60ch;
    margin: 0 0 30px;
  }
  .meta {
    display: flex;
    flex-wrap: wrap;
    gap: 8px 10px;
    font-family: var(--data);
    font-size: 12px;
    color: var(--ink-2);
  }
  .meta span {
    border: 1px solid var(--line);
    border-radius: 3px;
    padding: 4px 9px;
    background: var(--surface);
  }
  .meta span b { font-weight: 600; color: var(--ink); }

  /* ─────────── section scaffolding ─────────── */
  section { padding-top: 58px; }

  .sec-head {
    display: grid;
    grid-template-columns: var(--gutter) minmax(0, 1fr);
    gap: 0 8px;
    align-items: baseline;
    margin-bottom: 22px;
  }
  .sec-num {
    font-family: var(--data);
    font-size: 12px;
    letter-spacing: .1em;
    color: var(--accent);
    padding-top: 6px;
  }
  h2 {
    font-family: var(--display);
    font-weight: 700;
    letter-spacing: -0.032em;
    font-size: clamp(25px, 3.4vw, 33px);
    line-height: 1.12;
    margin: 0;
    text-wrap: balance;
  }
  h3 {
    font-family: var(--display);
    font-weight: 700;
    letter-spacing: -0.022em;
    font-size: 19px;
    line-height: 1.25;
    margin: 0 0 8px;
  }

  .body { display: grid; grid-template-columns: var(--gutter) minmax(0, 1fr); gap: 0 8px; }
  .body > .rail {
    font-family: var(--data);
    font-size: 11px;
    letter-spacing: .1em;
    text-transform: uppercase;
    color: var(--ink-3);
    padding-top: 7px;
  }
  .body > .flow { min-width: 0; }
  .flow > * + * { margin-top: 16px; }
  .flow p { margin: 0; max-width: var(--col); }
  .flow ul, .flow ol { margin: 0; padding-left: 20px; max-width: var(--col); }
  .flow li + li { margin-top: 7px; }

  @media (max-width: 700px) {
    .sec-head, .body { grid-template-columns: 1fr; }
    .body > .rail { padding: 0 0 8px; }
    :root { --gutter: 0px; }
  }

  code, .num {
    font-family: var(--data);
    font-size: .88em;
    font-variant-numeric: tabular-nums;
  }
  code {
    background: var(--surface-2);
    border-radius: 3px;
    padding: 1px 5px;
    color: var(--ink);
    overflow-wrap: anywhere;
  }
  a { color: var(--accent); text-decoration-thickness: 1px; text-underline-offset: 2px; }
  a:focus-visible, summary:focus-visible {
    outline: 2px solid var(--accent);
    outline-offset: 3px;
    border-radius: 2px;
  }

  /* ─────────── the thesis panel ─────────── */
  .thesis {
    background: var(--deep);
    color: var(--deep-ink);
    border-radius: 6px;
    padding: 30px 30px 26px;
    margin-top: 8px;
  }
  .thesis h3 { color: #FFFFFF; font-size: 21px; margin-bottom: 12px; }
  .thesis p { color: #C9DDFF; margin: 0; max-width: 62ch; }
  .thesis p + p { margin-top: 12px; }
  .thesis code {
    background: rgba(255,255,255,.1);
    color: #FFFFFF;
  }

  /* ─────────── tables ─────────── */
  .tw {
    overflow-x: auto;
    border: 1px solid var(--line);
    border-radius: 5px;
    background: var(--surface);
    box-shadow: var(--shadow);
  }
  table {
    border-collapse: collapse;
    width: 100%;
    min-width: 480px;
    font-size: 14.5px;
  }
  th, td {
    text-align: left;
    padding: 10px 14px;
    border-bottom: 1px solid var(--line-soft);
    vertical-align: top;
  }
  thead th {
    font-family: var(--data);
    font-size: 11px;
    letter-spacing: .09em;
    text-transform: uppercase;
    color: var(--ink-3);
    font-weight: 600;
    background: var(--surface-2);
    border-bottom: 1px solid var(--line);
    white-space: nowrap;
  }
  tbody tr:last-child td { border-bottom: 0; }
  td.n, th.n {
    font-family: var(--data);
    font-variant-numeric: tabular-nums;
    white-space: nowrap;
  }
  td .rc {
    font-family: var(--data);
    font-size: 11.5px;
    color: var(--accent);
    white-space: nowrap;
  }
  .bad  { color: var(--bad);  font-weight: 600; }
  .good { color: var(--good); font-weight: 600; }

  .chip {
    display: inline-block;
    font-family: var(--data);
    font-size: 11px;
    letter-spacing: .05em;
    padding: 2px 7px;
    border-radius: 3px;
    white-space: nowrap;
  }
  .chip.bad  { background: var(--bad-wash);  color: var(--bad); }
  .chip.good { background: var(--good-wash); color: var(--good); }
  .chip.info { background: var(--accent-wash); color: var(--accent); }

  /* ─────────── root-cause cards ─────────── */
  .rc-card {
    background: var(--surface);
    border: 1px solid var(--line);
    border-radius: 5px;
    padding: 22px 24px;
    box-shadow: var(--shadow);
  }
  .rc-card.primary { border-color: var(--bad); }
  .rc-head {
    display: flex;
    flex-wrap: wrap;
    align-items: baseline;
    gap: 10px;
    margin-bottom: 10px;
  }
  .rc-id {
    font-family: var(--data);
    font-size: 12px;
    font-weight: 600;
    letter-spacing: .06em;
    color: var(--accent);
  }
  .rc-card.primary .rc-id { color: var(--bad); }
  .rc-head h3 { margin: 0; flex: 1 1 260px; }
  .rc-card p { margin: 0; max-width: var(--col); }
  .rc-card > * + * { margin-top: 13px; }
  .rc-where {
    font-family: var(--data);
    font-size: 12px;
    color: var(--ink-3);
  }

  pre {
    margin: 0;
    background: var(--surface-2);
    border: 1px solid var(--line-soft);
    border-radius: 4px;
    padding: 13px 15px;
    overflow-x: auto;
    font-family: var(--data);
    font-size: 12.5px;
    line-height: 1.55;
    color: var(--ink);
  }
  pre code { background: none; padding: 0; font-size: inherit; }

  /* ─────────── the stack-rows evidence graphic ─────────── */
  .rows-viz {
    display: grid;
    gap: 7px;
    font-family: var(--data);
    font-size: 12px;
    font-variant-numeric: tabular-nums;
  }
  .rows-row {
    display: grid;
    grid-template-columns: 92px 1fr 78px;
    align-items: center;
    gap: 12px;
  }
  .rows-track {
    position: relative;
    height: 20px;
    background: var(--surface-2);
    border-radius: 3px;
    overflow: hidden;
  }
  .rows-fill {
    position: absolute;
    inset: 0 auto 0 0;
    background: var(--accent-soft);
    border-radius: 3px;
  }
  .rows-target {
    position: absolute;
    top: -3px;
    bottom: -3px;
    width: 2px;
    background: var(--bad);
  }
  .rows-row .label { color: var(--ink-2); }
  .rows-row .val { color: var(--bad); font-weight: 600; }
  .rows-legend {
    display: flex;
    flex-wrap: wrap;
    gap: 16px;
    font-family: var(--data);
    font-size: 11.5px;
    color: var(--ink-3);
    margin-top: 12px;
  }
  .rows-legend i { font-style: normal; }
  .swatch {
    display: inline-block;
