<title>The 44-Pixel Rule</title>
<style>
  /* ─────────── tokens: light is the base set ─────────── */
  :root {
    --ground:      #F1F3F8;
    --surface:     #FFFFFF;
    --surface-2:   #E9EDF6;
    --deep:        #040D6D;   /* the product's navy — used as a deep panel */
    --deep-ink:    #BFD8FF;

    --ink:         #0B1338;
    --ink-2:       #4A5378;
    --ink-3:       #838CAB;

    --accent:      #1F6FE0;
    --accent-soft: #58ABFF;   /* the product's blue */
    --accent-wash: #E3EDFC;

    --bad:         #BE3346;
    --bad-wash:    #FBE7EA;
    --good:        #0B8F62;
    --good-wash:   #E0F4EC;

    --line:        #D9DEEC;
    --line-soft:   #E7EBF4;

    --shadow:      0 1px 2px rgba(11,19,56,.05), 0 8px 24px -12px rgba(11,19,56,.18);

    --display: "Outfit", "Avenir Next", "Segoe UI Variable Display", system-ui, -apple-system, sans-serif;
    --body: system-ui, -apple-system, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    --data: ui-monospace, "SF Mono", SFMono-Regular, "JetBrains Mono", Menlo, Consolas, monospace;

    --col: 68ch;
    --gutter: 88px;
  }

  @media (prefers-color-scheme: dark) {
    :root:not([data-theme="light"]) {
      --ground:      #060A22;
      --surface:     #0C1231;
      --surface-2:   #121A40;
      --deep:        #020730;
      --deep-ink:    #8FBEFF;

      --ink:         #E9ECF7;
      --ink-2:       #A3ABC9;
      --ink-3:       #6D779C;

      --accent:      #74B6FF;
      --accent-soft: #58ABFF;
      --accent-wash: #13224C;

      --bad:         #FF8592;
      --bad-wash:    #35141C;
      --good:        #45D9A4;
      --good-wash:   #0C2C22;

      --line:        #1F2A56;
      --line-soft:   #162044;

      --shadow:      0 1px 2px rgba(0,0,0,.4), 0 8px 28px -14px rgba(0,0,0,.7);
    }
  }

  :root[data-theme="dark"] {
    --ground:      #060A22;
    --surface:     #0C1231;
    --surface-2:   #121A40;
    --deep:        #020730;
    --deep-ink:    #8FBEFF;

    --ink:         #E9ECF7;
    --ink-2:       #A3ABC9;
